PROTECTED_PROJECT = {'tests/volume_layout_test.cpp': '8ac62a56526cbadaecbe92785665176fb653ae40c54c14df01e8b92be4a8f527', 'scripts/test_volume_layout.ps1': '10f5349ab3aecc11228bdaa363bddb2ca1e13cd586129a2696bb03c793c732e8', 'plugins/l4n/L4D2BridgePlugin.cpp': '497339e0937c231965630b506ab042832589821a023ed678d3547b219d5d7c65'}
VOLUME_HANDLERS = {'IDirect3DVolume9_UnlockBox': '4d8c518fb453a3a27a4cad09de54bfb89cf75556e51305f0ae7c6aacef7629bc', 'IDirect3DVolumeTexture9_UnlockBox': '8bc4482d0ea7c4b4aaad70c70bbdbb1a85ca7064acedeb2aee96b8b50219defe'}


class RuntimeSeparation(unittest.TestCase):
    def test_core_allocator_and_optional_diagnostic_storage(self):
        client = SOURCE / 'bridge/src/client'
        allocator = (client / 'buffer_shadow.h').read_text(encoding='utf-8')
        observer = (client / 'memory_diagnostics.h').read_text(encoding='utf-8')
        buffer = (client / 'lockable_buffer.h').read_text(encoding='utf-8')
        self.assertIn('new uint8_t[size]', allocator)
        self.assertNotIn('new uint8_t[', observer)
        self.assertIn('l4d2_buffer::allocate', buffer)
        # Match the removed allocating function, not the allocated() notification.
        self.assertNotRegex(buffer, r'l4d2_memory::allocate\b')
        wait = (SOURCE / 'bridge/src/util/api_wait_diagnostics.h').read_text(encoding='utf-8')
        crash = (SOURCE / 'bridge/src/util/exception_diagnostics.cpp').read_text(encoding='utf-8')
        self.assertNotIn('inline ThreadStats threads[kThreads]', wait)
        self.assertNotIn('thread_local ThreadState s_thread', crash)

    def test_allocator_guard_distinguishes_notification(self):
        pattern = r'l4d2_memory::allocate\b'
        for text in ('l4d2_memory::allocate(size)', 'l4d2_memory::allocate (size)', '&l4d2_memory::allocate'):
            self.assertRegex(text, pattern)
        self.assertNotRegex('l4d2_memory::allocated(size, kind)', pattern)

    def test_diagnostic_log_cannot_trigger_policy_fallback(self):
        retention = (SOURCE / 'bridge/src/client/retention_runtime.h').read_text(encoding='utf-8')
        self.assertNotIn('policy-log-unavailable', retention)
        self.assertIn('void initializeDiagnostics() noexcept', retention)
        self.assertIn('persistent-db-open-or-validation-failed', retention)
        self.assertIn('unsupported-shared-heap-or-backend', retention)

    def test_protected_volume_abi_reset_host_and_plugin(self):
        for name, digest in PROTECTED_RUNTIME.items():
            with self.subTest(name=name):
                self.assertEqual(hashlib.sha256((SOURCE / name).read_bytes()).hexdigest(), digest)
        for name, digest in PROTECTED_PROJECT.items():
            with self.subTest(name=name):
                self.assertEqual(hashlib.sha256((ROOT / name).read_bytes().replace(b"\r\n", b"\n")).hexdigest(), digest)
        server = (SOURCE / 'bridge/src/server/main.cpp').read_text(encoding="utf-8")
        for name, digest in VOLUME_HANDLERS.items():
            start = server.index('      case ' + name + ':')
            end = server.index('      case ', start + 10)
            self.assertEqual(hashlib.sha256(server[start:end].encode()).hexdigest(), digest)

    def test_original_volume_lock_layout_is_unchanged(self):
        from scripts.generate_buffer_contract_test import method
        contents = (SOURCE / 'bridge/src/client/d3d9_volume.cpp').read_text(encoding='utf-8')
        start, end = method(contents, 'HRESULT Direct3DVolume9_LSS::lock(')
        self.assertEqual(hashlib.sha256(contents[start:end].encode()).hexdigest(), "591148f996f95255fde3ec9d33116a33beb1d88b68ba4b126ddd69d5f85f5a1c")

    def test_packaged_defaults_and_independent_monitoring(self):
        config = (ROOT / 'config/bridge.conf').read_text(encoding="utf-8")
        for side in ['client', 'server']:
            for switch in ['memoryMonitoring', 'crashDiagnostics', 'apiWaitDiagnostics',
                           'dataDiagnostics', 'colorDiagnostics', 'steamInputDiagnostics', 'steamOverlayInput']:
                self.assertRegex(config, re.escape(side + '.' + switch) + r'\s*=\s*False')
        self.assertRegex(config, r'client.pageBlockRetentionPolicy\s*=\s*learned-aggressive')
        for file, side in [('client/d3d9_lss.cpp', 'client'), ('server/main.cpp', 'server')]:
            startup = (SOURCE / ('bridge/src/' + file)).read_text(encoding="utf-8")
            self.assertIn('memoryMonitoring = Config::getOption<bool>("' + side + '.memoryMonitoring", false)', startup)
        options = (SOURCE / 'bridge/meson_options.txt').read_text(encoding="utf-8")
        self.assertRegex(options, r"option\('enable_tracy',\s*type\s*:\s*'boolean',\s*value\s*:\s*false")

    def test_logging_producers_are_lazy_and_command_guarded(self):
        for folder in ['client', 'server', 'util']:
            for path in (SOURCE / ('bridge/src/' + folder)).rglob('*.cpp'):
                if path.name == 'log.cpp':
                    continue
                self.assertNotRegex(path.read_text(encoding="utf-8"), r'Logger::(?:debug|trace)\(')
        server = (SOURCE / 'bridge/src/server/main.cpp').read_text(encoding="utf-8")
        self.assertRegex(server, r'if \(GlobalOptions::getLogServerCommands\(\)\)\s*\{\s*Logger::info\("Device Processing:')
        module = (SOURCE / 'bridge/src/server/module_processing.cpp').read_text(encoding="utf-8")
        self.assertRegex(module, r'if \(GlobalOptions::getLogServerCommands\(\)\)\s*\{\s*Logger::info')
        logger = (SOURCE / 'bridge/src/client/d3d9_util.h').read_text(encoding="utf-8")
        self.assertIn('FunctionEntryExitLogger(const char* functionName', logger)
        self.assertNotIn('>> s_counters;', logger)


